let nearbyFor='',nearbyItems=[],nearbyRegions=[],nearbyHere=null,nearbyBusy=false,nearbyJob=null;
function loadNearby(){if(nearbyBusy&&nearbyJob)return nearbyJob;nearbyJob=loadNearby0();return nearbyJob;}
async function loadNearby0(){const L=p.location;if(!L?.lon||!L?.lat)return;const key=L.lon.toFixed(5)+','+L.lat.toFixed(5);if(key===nearbyFor||nearbyBusy)return;nearbyBusy=true;try{const r=await fetch(`/api/nearby?x=${L.lon}&y=${L.lat}`);const d=await r.json();if(d.ok){nearbyItems=d.items||[];nearbyRegions=d.regions||[];nearbyHere=d.here||null;source(p,d.source);}else nearbyItems=[];nearbyFor=key;}catch{nearbyItems=[];nearbyFor=key;}finally{nearbyBusy=false;}siteStory();}
function siteStory(){const el=$('siteStory');if(!el)return;if(!p.pnu||!p.location?.lon){el.hidden=true;p.context=null;return;}loadNearby();const zone=p.land?.zone?.value||'';const c=siteContext({zone,places:nearbyItems,buildings:p.geometry?.buildings||[],terrainPoints:p.model?.terrain?.points||null});
 const dirs=siteDirections(nearbyItems,nearbyRegions,nearbyHere);c.dirs=dirs;c.dirSentence=directionSentence(dirs);
 const L=p.review?.limits,cap=number(p.manual?.floorLimit)>0,lh=L?.legalHeight,floors=L?(cap?number(p.manual.floorLimit):lh?.floors>0?lh.floors:(L.maxGross>0&&L.maxFootprint>0?Math.ceil(L.maxGross/L.maxFootprint-1e-9):null)):null;
 let allowedList=null;try{allowedList=allowedUses(p);}catch{}
 const SKIP=/위험물|자원순환|묘지|장례|교정|국방|군사|발전시설|방송통신|분뇨|위락|자동차 관련|동물 및 식물|야영장|운수시설/;
 const cand=(allowedList||[]).filter(x=>!SKIP.test(x.use));const allowed=allowedList?new Set(allowedList.map(x=>x.use)):null;
 const near=k=>nearbyItems.some(o=>o.kind===k&&o.distance<=(k==='지하철역'?500:800));const ts=terrainSummary(p.model?.terrain?.points||null);
 const score=u=>{let v=0;if(/근린생활|업무|판매/.test(u)&&near('지하철역'))v+=3;if(/상업/.test(zone)&&/근린생활|업무|판매|숙박/.test(u))v+=2;if(/주거/.test(zone)&&/주택|제1종/.test(u))v+=2;if(/녹지|관리/.test(zone)&&/단독주택|근린생활/.test(u))v+=2;if((near('공원')||nearbyItems.some(o=>o.kind==='경관-산'&&o.distance<1500))&&/주택|문화|관광|제2종/.test(u))v+=1;if(ts&&ts.slope>=8&&/단독주택/.test(u))v+=2;if(/공업/.test(zone)&&/공장|창고/.test(u))v+=3;return v;};
 const ranked=cand.map(x=>x.use).sort((a,b)=>score(b)-score(a));
 if(cand.length&&(!Array.isArray(p.storyUses)||p.storyUsesFor!==p.pnu)){p.storyUses=p.purpose&&cand.some(x=>x.use===p.purpose)?[p.purpose]:ranked.slice(0,3);p.storyUsesFor=p.pnu;}if(!Array.isArray(p.storyUses))p.storyUses=[];
 p.storyUses=p.storyUses.filter(u=>cand.some(x=>x.use===u));
 const uses=p.storyUses;c.useOptions=cand;
const b=selectedBuilding(p),from=b?.mainPurpsCdNm||'';
 const req=u=>{if(!L||L.maxFootprint==null)return[];const r=[];if(floors)r.push(`지상 ${floors}층 이하`);r.push(`건축면적 ${fmt(L.maxFootprint,2)}㎡ 이하`);if(L.maxGross!=null)r.push(`연면적 ${fmt(L.maxGross,2)}㎡ 이하`);if(L.parking!=null&&(!L.parkingPurpose||String(L.parkingPurpose).includes(u.replace(/^제\d종\s*/,''))||u===L.parkingPurpose))r.push(`부설주차 ${fmt(L.parking)}대`);else r.push('부설주차 용도별 별도 산정');if(L.landscapeExempt)r.push('조경 면제');else if(L.landscapeArea!=null)r.push(`조경 ${fmt(L.landscapeArea,2)}㎡ 이상`);const ck=scaleChecklist({zone,purpose:u,floors,gross:L.maxGross});for(const x of ck)if(/대상$|허가 대상|신고 가능|적용$|검토$/.test(x.result))r.push(`${x.item}: ${x.result}`);return r;};
 const change=u=>from?useChange(from,u)?.text||null:null;
 c.stories=useStories({uses,dirs,ctx:c,terrain:ts,pnu:p.pnu,req,change,allowed});c.usesFromFallback=false;
 c.checklist=L?scaleChecklist({zone,purpose:p.purpose||'',floors,gross:L.maxGross}):[];
 p.context=c;p.contextText=contextText(p.address,c)+(c.dirSentence?'\n\n■ 동서남북\n'+stripMarks(c.dirSentence):'')+(c.stories?.length?'\n\n■ 용도별 건축 이야기\n'+c.stories.map(s=>`[${s.use}] ${stripMarks(s.story)}\n  요건: ${s.requirements.join(' · ')}${s.change?'\n  용도변경: '+s.change:''}`).join('\n'):'');
 const hl=t=>esc(t).replace(/«([^»]+)»/g,'<span class="loc">$1</span>');
 const li=a=>a.map(x=>`<li>${esc(x)}</li>`).join('');const sig=c.signature.map(o=>`<li><b>${esc(o.name)}</b> <small>${esc(o.kind)} · ${Math.round(o.distance).toLocaleString('ko-KR')}m</small></li>`).join('');
 const waiting=nearbyFor?'':'<p class="small muted">주변 시설 조회 중…</p>';
 const chips=cand.length?`<div class="use-chips" role="group" aria-label="이야기를 만들 용도 선택">${cand.map(x=>`<button type="button" class="use-chip${uses.includes(x.use)?' on':''}" data-use="${esc(x.use)}">${esc(x.use)}${x.cond?' <small>조건부</small>':''}</button>`).join('')}</div>`:'<p class="uncertain small">허용 용도 판정 자료(국토계획법 시행령 별표) 수신 전 — 용도별 이야기는 판정 후 표시</p>';
 const stories=c.stories.map(s=>`<div class="ctx-use"><b>${esc(s.use)}</b>${s.allowed===false?' <span class="uncertain small">허용 용도 아님</span>':''}<p>${hl(s.story)}</p>${s.requirements.length?`<p class="ctx-req"><span>건축 요건</span> ${esc(s.requirements.join(' · '))}</p>`:''}${s.change?`<p class="ctx-req uncertain"><span>용도변경</span> ${esc(s.change)}</p>`:''}</div>`).join('');
 el.innerHTML=`<h3>대지 맥락 · 컨셉 <small class="muted">자동 생성 참고 자료</small></h3>${waiting}${c.character?`<p class="ctx-char">${esc(c.character)}</p>`:''}${c.dirSentence?`<p class="ctx-dir">${hl(c.dirSentence)}</p>`:''}${c.story?`<p class="ctx-story">${esc(c.story)}</p>`:''}${c.facts.length?`<h4>주변 현황</h4><ul>${li(c.facts)}</ul>`:''}${sig?`<h4>주변 주요 시설</h4><ul class="ctx-sig">${sig}</ul>`:''}${c.concepts.length?`<h4>계획 착안점</h4><ul>${li(c.concepts)}</ul>`:''}<h4>용도별 건축 이야기 <small class="muted">허용 용도 중 선택 (여러 개 가능)</small></h4>${chips}${stories}${c.cautions.length?`<h4>유의사항</h4><ul class="uncertain">${li(c.cautions)}</ul>`:''}<p class="uncertain small">${esc(c.assumptions.join(' · '))}. 건축 요건은 법정 최대 규모 기준 규칙 판정. 설계 판단은 건축사 검토를 거칠 것.${p.model?.terrain?'':' 지형 자료 수신 후 지형 항목이 추가됨.'}</p>`;el.hidden=false;}
const ensureContext=async()=>{for(let i=0;i<30&&document.querySelector('.tools .ld.loading');i++){log('자료 조회 마무리 대기…');await new Promise(r=>setTimeout(r,500));}try{await Promise.race([loadNearby(),new Promise(r=>setTimeout(r,8000))]);}catch{}try{siteStory();}catch(e){console.warn(e);}};
const ready=()=>{if(!p.pnu)throw new Error('지번을 먼저 조회하십시오. 조회 전에는 문서를 만들지 않습니다.');};

/* 법정 최대 3가지(건폐율·용적률·높이)와 층수 관계를 한 줄씩 */
function threeMax(l,n,cap,lh){const sm=(cap||lh?.floors)?null:sunlightMaxFloors(p);const F=(v,d=2)=>v==null?'-':fmt(v,d);
 const h=cap?`적용 최고층수 ${fmt(n)}층`:lh?.floors?`법령 층수 제한 ${fmt(n)}층 이하`:sm?`법정 제한 없음 (정북 일조 사선만 적용 시 이론상 높이 ${F(sm.height,1)} m · ${fmt(sm.floors)}층)`:'법정 제한 없음';
 const g=l.maxGross,fp=l.maxFootprint,full=fp>0&&g>0?Math.ceil(g/fp-1e-9):null;
 return `<ol class="three-max"><li><b>건폐율 최대</b> ${F(l.bcr?.value,0)}% → 건축면적 최대 <b>${F(fp)} ㎡</b></li><li><b>용적률 최대</b> ${F(l.far?.value,0)}% → 지상 연면적 최대 <b>${F(g)} ㎡</b></li><li><b>높이 최대</b> <span class="${cap||lh?.floors?'':'uncertain'}">${esc(h)}</span></li></ol><p class="small three-note">층수 = 연면적 ÷ 한 층 면적. 건축면적을 최대로 채우면 ${full??'-'}층이고, 층수를 올리면 한 층 면적이 줄어듭니다(예: ${full?full*2:'-'}층이면 한 층 약 ${full?F(g/(full*2)):'-'} ㎡).</p>`;}
function maxSummary(){const el=$('maxSummary');if(!el)return;const l=p.review?.limits;if(!p.pnu||!l||l.maxFootprint==null){el.hidden=true;return;}const cap=number(p.manual.floorLimit)>0;const lh=l.legalHeight;const n=cap?number(p.manual.floorLimit):lh?.floors>0?lh.floors:Math.ceil(l.maxGross/l.maxFootprint-1e-9);if(p.legalMaxFloors!==n){p.legalMaxFloors=n;if(!(number(p.floors)>0)||(number(p.floors)>n&&(cap||lh?.floors>0))){p.floors=n;$('floors').value=n;}try{floorChips();}catch{}}
 const rr=!!(l.bcr.uncertain||l.far.uncertain);const box=(k,v,u,sub='',red=false)=>`<div class="${red?'red':''}"><span>${k}</span><b>${v}</b><small>${u}</small>${sub?`<em>${sub}</em>`:''}</div>`;
 el.innerHTML=`<h3>이 대지의 법정 최대</h3>${threeMax(l,n,cap,lh)}<div class="max-grid">${(cap||lh?.floors?box('지상 최대 층수',fmt(n),'층',cap?'적용 최고층수 기준':'법령 층수 제한',false):(()=>{const sm=sunlightMaxFloors(p);return sm?box('지상 최대 층수','법정 제한 없음','',`정북 일조 사선만 적용하면 이론상 ${fmt(sm.floors)}층 (대지 남북 길이 ${fmt(sm.depth,1)} m × 2 = 높이 ${fmt(sm.height,1)} m, 층고 가정) — 실제는 공동주택 채광·인동거리·지구단위계획·심의로 결정`,true):box('지상 최대 층수','제한 없음','',`법정 층수 제한 없음 · 높이는 공동주택 채광·인동거리, 대지 안의 공지, 지구단위계획 등으로 정해짐`,true);})())}${box('건폐율',fmt(l.bcr.value),'%','',!!l.bcr.uncertain)}${box('용적률',fmt(l.far.value),'%','',!!l.far.uncertain)}${box('최대 건축면적',fmt(l.maxFootprint,2),'㎡','',rr)}${box('최대 연면적',fmt(l.maxGross,2),'㎡','',rr)}${box('부설주차',l.parking!=null?fmt(l.parking):'',l.parking!=null?'대':'',l.parking==null?'산정 불가':l.parkingPurposeAssumed?'주용도 미선택 · '+esc(l.parkingPurpose)+' 가정':esc(l.parkingPurpose),l.parking==null||rr||!!l.parkingPurposeAssumed)}${box('조경면적',l.landscapeArea!=null?fmt(l.landscapeArea,2):'',l.landscapeArea!=null?'㎡':'',l.landscapeExempt?'조경 의무 면제 대상':l.landscapeArea==null?'조례 비율 추출 불가':l.landscapeOptional?'조례 기준 · 녹지지역 면제 선택 가능':'',l.landscapeArea==null||(rr&&!l.landscapeExempt))}</div><p class="small" style="margin:10px 0 2px"><b>부설주차 산식</b> ${esc(l.parkingFormula||'')}</p><p class="small" style="margin:0 0 8px"><b>조경면적 산식</b> ${esc(l.landscapeFormula||'')}</p><p class="uncertain small">${l.district?'지구단위계획구역 : 시행지침의 높이·층수·용적률이 우선 적용되므로 실제 최대는 이보다 낮을 수 있음. ':''}${lh?.lines?.length?lh.lines.join(' / ')+'. ':''}${cap||lh?.floors?'':'층수는 법정 높이 제한이 아닌 비율 산정치(대지 안의 공지·건축선 후퇴 미반영). '}05 계획 조건에서 층수·용도를 바꾸면 다시 계산됨.</p>`;el.hidden=false;}

/* 용도 선택 칸: 법령상 건축 가능한 용도만 표시 */
function refreshUses(){const list=allowedUses(p);const key=JSON.stringify(list)+p.land.zone.value;if(key===usesKey)return;usesKey=key;for(const [id,empty] of [['purpose','선택하지 않음'],['purpose2','없음']]){const sel=$(id),cur=sel.value;const items=list?list:USES.map(u=>({use:u,cond:true}));sel.innerHTML=`<option value="">${empty}</option>`+items.map(x=>`<option value="${esc(x.use)}"${x.cond?' style="color:#e00000"':''}>${esc(x.use)}${x.cond?' (조건부·조례 대조)':''}</option>`).join('');if(items.some(x=>x.use===cur))sel.value=cur;else if(cur){sel.value='';}}
 const note=$('usesNote');if(note)note.innerHTML=list?`<span class="uncertain">${esc(p.land.zone.value)}${p.land.zones.some(z=>z.name.includes('개발제한구역'))?'·개발제한구역':''}에서 법령상 건축 가능한 용도 ${list.length}개만 표시. 빨간 항목은 조건부(조례·입지 요건) 허용.</span>`:'<span class="uncertain">용도지역 건축제한 원문 수신 전 — 전체 용도 표시</span>';}

/* 토지이음 순서: 용도지역 → 도시지역 등 → 용도지구 → 용도구역 → 지구단위계획 → 다른 법령. 같은 이름은 한 번만. */
function sortZones(zs){const rank=n=>ZONES.includes(n)?0:/^(도시|관리|농림|자연환경보전)지역$/.test(n)?1:/지구$/.test(n)&&!/지구단위|취락/.test(n)?2:/개발제한구역|도시자연공원구역|시가화조정구역|수산자원보호구역|입지규제최소구역/.test(n)?3:/지구단위계획|취락지구/.test(n)?4:5;const seen=new Set();return zs.filter(z=>{if(seen.has(z.name))return false;seen.add(z.name);return true;}).map((z,i)=>[z,i]).sort((a,b)=>rank(a[0].name)-rank(b[0].name)||a[1]-b[1]).map(x=>x[0]);}

async function loadBuildings(project){const kinds=['title','recap','floors','exclusive'];const r=await pool(kinds.map(kind=>()=>paged('/api/buildings',{kind,pnu:project.pnu},project)));r.forEach((d,i)=>{if(d.ok)project.building[{title:'titles',recap:'recaps',floors:'floors',exclusive:'exclusive'}[kinds[i]]]=d.items;});project.building.status=r[0].ok?(r[0].total===0?'empty':'loaded'):'unavailable';for(const x of r)if(x.error)log(x.error.message,true);}
document.addEventListener('click',e=>{if(e.target.id!=='reloadBuilding'||!p.pnu)return;reloadPart('building');});
/* 점검용: 현재 프로젝트 읽기 전용 참조 */
Object.defineProperty(window,'__aom',{value:{get p(){return p;},get model(){return modelResult;}}});


/* 여러 필지 표 (02 토지 · 03 건축물 · 주소 카드) */
function parcelLandTable(){const rows=parcelRows(p);if(rows.length<2)return'';const tot=rows.reduce((s,r)=>s+(r.area||0),0),zs=new Set(rows.map(r=>r.zone));const M=p.review?.multi;
 return `<div class="parcel-box"><h3>필지별 현황 (${rows.length}필지)</h3><table class="table parcel-t"><thead><tr><th>구분</th><th>지번</th><th>면적(㎡)</th><th>지목</th><th>용도지역</th><th>공시지가(원/㎡)</th><th>열람</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td class="c">${i?'추가 '+i:'대표'}</td><td>${esc(r.address||'')}</td><td class="n">${r.area!=null?fmt(r.area,2):'<span class="uncertain">미수집</span>'}</td><td class="c">${esc(r.category)}</td><td class="c ${r.zone?'':'uncertain'}">${esc(r.zone||'미수집')}${new Set(r.zones).size>1?' <span class="uncertain">(필지 안에서 용도지역 나뉨)</span>':''}</td><td class="n">${r.price!=null?fmt(r.price):'<span class="uncertain">미수집</span>'}</td><td class="c">${eumUrl(r.pnu)?`<a href="${eumUrl(r.pnu)}" target="_blank" rel="noopener">토지이음 ↗</a>`:''}</td></tr>`).join('')}<tr class="sum"><td class="c">합계</td><td></td><td class="n">${fmt(tot,2)}</td><td></td><td class="c">${zs.size>1?'<span class="uncertain">용도지역 '+zs.size+'개</span>':esc([...zs][0]||'')}</td><td></td><td></td></tr></tbody></table>${zs.size>1&&M?.ruleText?`<p class="uncertain small">용도지역이 서로 다름 → ${esc(M.ruleText)}. 대지 전체 환산 건폐율 ${fmt(p.review.limits.bcr?.value)}% · 용적률 ${fmt(p.review.limits.far?.value)}% (「국토의 계획 및 이용에 관한 법률」 제84조, 같은 법 시행령 제94조 — 08 건축 사전 검토 자료의 관련 법령에서 원문 확인).</p>`:''}${M?.note?`<p class="uncertain small">${esc(M.note)}</p>`:''}</div>`;}
function parcelBuildingTable(){const rows=parcelRows(p);if(rows.length<2)return'';
 return `<div class="parcel-box"><h3>필지별 건축물대장</h3><table class="table parcel-t"><thead><tr><th>지번</th><th>건축물</th><th>주용도</th><th>규모</th><th>연면적(㎡)</th><th>사용승인일</th></tr></thead><tbody>${rows.map(r=>{const B=r.building||{},ts=B.titles||[];if(!ts.length)return `<tr><td>${esc(r.address||'')}</td><td colspan="5" class="${B.status==='empty'?'':'uncertain'}">${B.status==='empty'?'등재 건축물 없음 (나대지 또는 다른 지번에 등재)':B.status==='unavailable'?'조회 실패 — 다시 불러오기':'자료 없음'}</td></tr>`;return ts.map((b,k)=>`<tr><td>${k?'':esc(r.address||'')}</td><td>${esc([b.bldNm,b.dongNm].filter(Boolean).join(' ')||'(명칭 없음)')}</td><td class="c">${esc(b.mainPurpsCdNm||'')}</td><td class="c">${[b.ugrndFlrCnt?'지하 '+b.ugrndFlrCnt:'',b.grndFlrCnt?'지상 '+b.grndFlrCnt+'층':''].filter(Boolean).join(' / ')}</td><td class="n">${b.totArea?fmt(b.totArea,2):''}</td><td class="c">${b.useAprDay?displayDate(b.useAprDay):''}</td></tr>`).join('');}).join('')}</tbody></table><p class="uncertain small">필지마다 위반건축물 여부를 세움터에서 각각 열람하십시오.</p></div>`;}
/* 지도 종류 버튼 · 주소 카드 · 기본 주소 */
for(const b of document.querySelectorAll('[data-mt]'))b.onclick=async()=>{await ensureMainMap();setMapType(b.dataset.mt);};
function addrCard(){const el=$('addrCard');if(!el)return;if(!p.pnu){el.hidden=true;return;}const loc=p.location||{};el.hidden=false;el.innerHTML=`<div class="ac-top"><b>${esc(p.address)}${p.extra?.length?` 외 ${p.extra.length}필지`:''}</b><button type="button" class="ac-x" id="acClear" aria-label="지우기">✕</button></div><div class="ac-meta">${loc.lat!=null?`<span>${Number(loc.lat).toFixed(5)}° N · ${Number(loc.lon).toFixed(5)}° E</span>`:''}</div><div class="ac-tags">${[p.land.category.value,totalArea(p)!=null?fmt(totalArea(p),2)+' ㎡':'',p.land.zone.value].filter(Boolean).map(t=>`<span>${esc(t)}</span>`).join('')}${p.extra?.length?`<span class="parcel-tag" data-open="s2">${p.extra.length+1}필지 · 필지별 현황 보기</span>`:''}${(p.building?.titles?.length||p.building?.recaps?.length)?'<span class="viol-badge" data-open="s3">기존 건물 있음 · 위반건축물 여부 세움터 열람</span>':''}</div>`;$('acClear').onclick=()=>$('resetProject').click();}

/* 항목별 불러오기 상태 표시 · 다시 불러오기 */
function setLoad(k,v){LOAD[k]=v;cardStatus();}
function cardStatus(){const map={s2:'land',s3:'building',s4:'laws',s6:'model',s7:'spatial'};for(const [sec,k] of Object.entries(map)){const b=document.querySelector(`.tools [data-open="${sec}"]`);if(!b)continue;let t=b.querySelector('.ld');if(!t){t=document.createElement('u');t.className='ld';b.querySelector('span').append(t);}const v=LOAD[k];t.className='ld'+(v?' '+v:'');t.textContent=v==='loading'?'불러오는 중…':v==='fail'?'받지 못함 · 눌러서 다시 불러오기':'';}}
async function loadLand(project){setLoad('land','loading');const r=await pool(['use','characteristics','price'].map(kind=>()=>paged('/api/land',{kind,pnu:project.pnu},project)));applyLandResponse(project,r.map(x=>x.error?{ok:false}:x));for(const x of r)if(x.error)log(x.error.message,true);setLoad('land',r.some(x=>x.error||x.ok===false)||project.land.area?.value==null?'fail':'ok');}
function reloadPart(k){if(!p.pnu)return toast('주소를 먼저 조회하십시오.');const run={land:()=>loadLand(p),building:async()=>{setLoad('building','loading');await loadBuildings(p);setLoad('building',p.building.status==='unavailable'?'fail':'ok');},spatial:async()=>{setLoad('spatial','loading');await loadSpatial(p);setLoad('spatial',(p.geometry.parcels||[]).length?'ok':'fail');maps();},laws:async()=>{setLoad('laws','loading');await loadLaws(p);setLoad('laws',p.laws.length?'ok':'fail');}}[k];if(!run)return;task('다시 불러오기',async()=>{await run();toInputs();render();updateModels(false);setLoad('model',modelResult?.models?.length?'ok':'fail');toast('다시 불러오기 완료.');});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-reload]');if(b){e.preventDefault();e.stopPropagation();reloadPart(b.dataset.reload);}});

/* 좌측 상단 A.O.M: 처음 화면(지도 도구 맨 위)으로 */
{const brand=document.querySelector('.top .brand');if(brand){brand.setAttribute('role','link');brand.tabIndex=0;brand.title='처음 화면으로';const go=()=>{document.querySelector('[data-tab="review"]')?.click();if(!$('drawer').hidden)closeDrawer();document.querySelector('.panel')?.scrollTo({top:0,behavior:'smooth'});window.scrollTo({top:0,behavior:'smooth'});};brand.onclick=go;brand.onkeydown=e=>{if(e.key==='Enter')go();};}}

/* 토지이음 필지 상세 바로가기 (PNU 기준) */
function eumUrl(pnu){if(!/^\d{19}$/.test(pnu||''))return 'https://www.eum.go.kr';const q=new URLSearchParams({selSido:pnu.slice(0,2),selSgg:pnu.slice(2,5),selUmd:pnu.slice(5,9),selRi:pnu.slice(9,11),landGbn:pnu[10]==='2'?'2':'1',bobn:String(+pnu.slice(11,15)),bubn:String(+pnu.slice(15,19)),pnu,scale:'',isNoScr:'script',chk:'0',mode:'search',selGbn:'umd'});return 'https://www.eum.go.kr/web/ar/lu/luLandDet.jsp?'+q;}
/* 시행지침 파일 읽기 · 조항 찾기 · 적용 */
function guideState(){const el=$('guideState');if(!el)return;const d=p.land.zones?.some(z=>/지구단위계획/.test(z.name));$('guideBox').hidden=!d;el.className=d&&!guidePages?'uncertain':'small';el.textContent=d?(guidePages?`'${guideName}' 읽음 — 아래에서 블록 조항을 확인하고 [적용]을 누르십시오.`:'이 대지는 지구단위계획구역입니다. 시행지침의 건폐율·용적률·높이·조경이 조례보다 우선하므로, 토지이음에서 시행지침을 내려받아 아래에 넣어야 수치가 확정됩니다. 지침을 넣기 전 수치는 시행지침 미대조 값입니다.'):(guidePages?`'${guideName}' 읽음.`:'지구단위계획구역이 아니면 넣지 않아도 됩니다.');}
function guideRender(){const el=$('guideResult');if(!el||!guidePages)return;const r=searchGuideline(guidePages,'');const unit={bcr:'%',far:'%',landscape:'%',floorLimit:'층',height:'m',buildingLine:'m'};
 el.innerHTML=r.topics.map(t=>`<details class="gb-topic"${t.hits.some(h=>h.inBlock)?' open':''}><summary><b>${esc(t.label)}</b> <small>${t.total}건</small></summary>${t.hits.length?t.hits.map(h=>`<div class="gb-hit${h.inBlock?' in':''}"><span class="pg">${h.section?esc(h.head||"본문"):h.page+"쪽"}</span><span class="tx">${esc(h.ctx)}</span>${['bcr','far','landscape','floorLimit','height'].includes(t.key)?h.values.slice(0,3).map(v=>`<button type="button" data-gapply="${t.key}" data-v="${v}">${v}${unit[t.key]} 적용</button>`).join(''):''}</div>`).join(''):'<p class="small">해당 문장 없음</p>'}</details>`).join('');}
async function guideFile(file){if(!file)return;task('시행지침 읽기',async()=>{guidePages=await readGuideline(file);guideName=file.name;const n=guidePages.reduce((a,b)=>a+b.lines.length,0);if(!n)throw new Error('파일에서 글자를 읽지 못했습니다. 스캔 이미지 PDF는 글자 인식이 되지 않습니다.');guideState();guideRender();toast(`시행지침 ${guidePages.length}쪽 읽음.`);});}
$('guideFile').onchange=e=>guideFile(e.target.files[0]);
const gd=$('guideDrop');gd.addEventListener('dragover',e=>{e.preventDefault();gd.classList.add('over');});gd.addEventListener('dragleave',()=>gd.classList.remove('over'));gd.addEventListener('drop',e=>{e.preventDefault();gd.classList.remove('over');guideFile(e.dataTransfer.files[0]);});
document.addEventListener('click',e=>{const b=e.target.closest('[data-gapply]');if(!b)return;const k=b.dataset.gapply,v=+b.dataset.v;p.manual[k]=v;if(k==='bcr'||k==='far'){p.manual.districtResolved=true;const c=$('districtResolved');if(c)c.checked=true;}const inp=$('rule-'+k);if(inp)inp.value=v;manualSource();render();autoMax();updateModels(false);toast(`시행지침 값 적용: ${b.textContent.replace(' 적용','')}`);});

/* 여러 필지: [＋ 필지 추가]를 누를 때마다 입력칸이 하나씩 생기고, 조회하면 대지에 합산 */
function extraRow(){const box=$('extraParcels'),row=document.createElement('div');row.className='xp-row';row.innerHTML='<input class="xp-in" placeholder="추가 필지 지번 (예: 부암동 99-2)"><button type="button" class="xp-go">추가</button><button type="button" class="xp-x" aria-label="삭제">✕</button><span class="xp-st small"></span>';box.append(row);row.querySelector('.xp-in').focus();
 hangulInput(row.querySelector('.xp-in'));const go=()=>addParcel(row);row.querySelector('.xp-go').onclick=go;row.querySelector('.xp-in').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();go();}};row.querySelector('.xp-x').onclick=()=>removeParcel(row);}
$('addParcel').onclick=()=>{if(!p.pnu)return toast('먼저 대표 필지 주소를 조회하십시오.');extraRow();};
async function addParcel(row){let q=row.querySelector('.xp-in').value.trim();if(!q)return;const st=row.querySelector('.xp-st');
 // '99-2'처럼 번지만 넣으면 대표 필지의 시·구·동을 붙임
 if(/^산?\s*\d+(-\d+)?$/.test(q)){const parts=p.address.split(/\s+/);q=parts.slice(0,-1).join(' ')+' '+q;}
 st.textContent='조회 중…';st.className='xp-st small';
 try{const d=await api('/api/address',{q});const it=(d.items||[]).find(a=>a.pnu&&norm(a.address)===norm(q))||(d.items||[]).find(a=>a.pnu);if(!it)throw new Error('주소를 찾지 못함');
  if(it.pnu===p.pnu||(p.extra||[]).some(x=>x.pnu===it.pnu))throw new Error('이미 들어간 필지');
  const kinds=['characteristics','price','use'],r={};for(const k of kinds){try{r[k]=await paged('/api/land',{kind:k,pnu:it.pnu},p);}catch(e){r[k]={ok:false};}}
  const latest=x=>x?.ok?[...x.items].sort((a,b)=>fieldDate(b).localeCompare(fieldDate(a)))[0]:null,c=latest(r.characteristics),v=latest(r.price);
  const parts=it.address.split(/\s+/);const rec={pnu:it.pnu,address:it.address,dong:parts.at(-2)||'',lot:parts.at(-1)||'',area:datum(c?number(c.lndpclAr):null,'브이월드 토지특성',!c),price:datum(v?number(v.pblntfPclnd):null,'브이월드 개별공시지가',!v),priceDate:datum(v?.stdrYear?`${v.stdrYear}-${String(v.stdrMt).padStart(2,'0')}`:null,'브이월드 개별공시지가',!v),category:c?.lndcgrCodeNm||'',location:it};
  {const nat=r.use?.ok?r.use.items.map(z=>z.prposAreaDstrcCodeNm).filter(n=>ZONES.includes(n)):[];rec.zones=[...new Set(nat)];rec.zone=rec.zones[0]||'';}
  try{const bt=await paged('/api/buildings',{kind:'title',pnu:it.pnu},p),br=await paged('/api/buildings',{kind:'recap',pnu:it.pnu},p);rec.building={titles:bt.ok?bt.items:[],recaps:br.ok?br.items:[],status:bt.ok?(bt.total===0?'empty':'loaded'):'unavailable'};}catch(e){rec.building={titles:[],recaps:[],status:'unavailable'};}
  if(r.use?.ok)for(const z of r.use.items.filter(z=>z.prposAreaDstrcCodeNm))if(!p.land.zones.some(x=>x.name===z.prposAreaDstrcCodeNm))p.land.zones.push({name:z.prposAreaDstrcCodeNm,lawName:z.lawNm||'',group:ZONES.includes(z.prposAreaDstrcCodeNm)?'national':z.lawNm?'other':'',uncertain:false,extra:it.pnu});
  if(!p.parcels.length){const ps=p.address.split(/\s+/);p.parcels=[{dong:ps.at(-2)||'',lot:ps.at(-1)||'',area:{...p.land.area},price:{...p.land.price},priceDate:{...p.land.priceDate}}];}
  p.parcels.push({dong:rec.dong,lot:rec.lot,area:rec.area,price:rec.price,priceDate:rec.priceDate,pnu:it.pnu,zone:rec.zone});(p.extra??=[]).push(rec);row.dataset.pnu=it.pnu;row.querySelector('.xp-in').value=it.address;row.querySelector('.xp-in').disabled=true;row.querySelector('.xp-go').hidden=true;
  // 지적도에서 대상 필지로 표시(주변 조회 범위 밖이면 그 위치 주변을 추가 조회)
  let hit=(p.geometry.parcels||[]).filter(f=>f.properties?.pnu===it.pnu);if(!hit.length){const tmp={...p,location:it,geometry:{parcels:[],buildings:[]}};await loadSpatial(tmp);const add=(tmp.geometry.parcels||[]).filter(f=>!(p.geometry.parcels||[]).some(g=>g.properties?.pnu===f.properties?.pnu));p.geometry.parcels.push(...add);hit=(p.geometry.parcels||[]).filter(f=>f.properties?.pnu===it.pnu);}
  for(const f of hit)f.properties.target=true;
  st.textContent=rec.area.value!=null?`${fmt(rec.area.value,2)}㎡ · ${rec.category}`:'면적 자료 없음';st.className='xp-st small'+(rec.area.value==null?' uncertain':'');
  render();autoMax();updateModels(false);maps();toast(`필지 추가: ${it.address} · 대지 합계 ${fmt(totalArea(p),2)}㎡`);}
 catch(e){st.textContent=e.message;st.className='xp-st small uncertain';}}
function removeParcel(row){const pnu=row.dataset.pnu;if(pnu){p.parcels=p.parcels.filter(x=>x.pnu!==pnu);p.extra=(p.extra||[]).filter(x=>x.pnu!==pnu);p.land.zones=p.land.zones.filter(z=>z.extra!==pnu);for(const f of p.geometry.parcels||[])if(f.properties?.pnu===pnu)f.properties.target=false;if(p.parcels.length===1&&!p.extra.length)p.parcels=[];render();autoMax();updateModels(false);maps();}row.remove();}

document.addEventListener('click',e=>{const b=e.target.closest('.use-chip');if(!b)return;const u=b.dataset.use;const a=Array.isArray(p.storyUses)?p.storyUses:[];p.storyUses=a.includes(u)?a.filter(x=>x!==u):[...a,u];try{siteStory();}catch(err){console.warn(err);}});
